var EDITABLE_ACF_SCALAR_FIELDS = [
  "price",
  "status",
  "radio_book_now",
  "start_date",
  "end_date",
  "time_frame",
  "location",
  "capacity",
  "single_room_price",
  "twin_room_per_person_price",
  "double_room_per_person_price",
  "payment_details",
  "add_download_brochure",
  "attach_brochure_here"
];
var EDITABLE_ACF_REPEATER_FIELDS = [
  "inclusions",
  "exclusions_details",
  "faqs_list",
  "add_review"
];
function sanitiseAcfUpdate(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return {};
  const out = {};
  const src = input;
  for (const key of EDITABLE_ACF_SCALAR_FIELDS) {
    if (key in src) {
      let v = src[key];
      if (key === "attach_brochure_here") {
        if (v === "" || v === null || v === void 0) {
          v = null;
        } else if (typeof v === "string" && /^\d+$/.test(v)) {
          v = Number(v);
        } else if (typeof v === "object" && v && "id" in v) {
          const idVal = v.id;
          v = typeof idVal === "number" ? idVal : Number(idVal);
        }
      }
      out[key] = v;
    }
  }
  for (const key of EDITABLE_ACF_REPEATER_FIELDS) {
    if (key in src) {
      const v = src[key];
      out[key] = Array.isArray(v) ? v : [];
    }
  }
  return out;
}

